-- Crews (generated by drizzle-kit), plus by hand:
-- 1. The first crew is created right after its table, before reactions.crew_id (which defaults to it)
--    gets its foreign key.
-- 2. Backfill: everyone joins the first crew (its owner as owner, and app admin), and every existing
--    review and check-in is shared with it. Old code writing during the deploy leaves posts without
--    links; the app reads those as the first crew's.
CREATE TABLE "checkin_crews" (
	"checkin_id" uuid NOT NULL,
	"crew_id" uuid NOT NULL,
	CONSTRAINT "checkin_crews_checkin_id_crew_id_pk" PRIMARY KEY("checkin_id","crew_id")
);
